    #[test]
    fn extends_env_override_replaces_ci_block() {
        let server = MockServer::start();

        let base_yaml = r#"
app_name: BaseApp
steps:
  db:
    command: "db-setup"
    environments:
      ci:
        command: "pg_isready"
