    for ext in extends {
        if ext.url.is_empty() {
            return Err(anyhow!("Extends URL cannot be empty"));
        }
        if !ext.url.starts_with("http://") && !ext.url.starts_with("https://") {
            return Err(anyhow!("Extends URL must be HTTP/HTTPS: {}", ext.url));
