    #[test]
    fn service_reachable_returns_satisfied_on_success() {
        use crate::requirements::registry::{Requirement, RequirementCheck};

        let temp = TempDir::new().unwrap();
        let probe = make_probe();
        let mut registry = RequirementRegistry::new();
        registry.insert(
