            max_depth: 2,
        };

        let result = resolver.resolve(&config);

        assert!(result.is_err());
        let err = result.unwrap_err().to_string();
        assert!(
            err.contains("depth exceeds"),
            "Error should mention depth: {}",
            err
        );
    }

