        let mut checker = GapChecker::new(&registry, &probe, temp.path());
        let status = checker.check_one("any-tool");
        assert!(
            matches!(status, RequirementStatus::Missing { .. }),
            "Any check should be Missing when no subcheck passes, got: {:?}",
