        server.mock(|when, then| {
            when.method(GET).path("/depth1.yml");
            then.status(200).body(depth1_yaml);
        });

        let config = BivvyConfig {
            extends: Some(vec![ExtendsConfig {
                url: server.url("/depth1.yml"),
