    use crate::error::BivvyError;

    const MAX_DEPTH: usize = 5;

    if depth > MAX_DEPTH {
        return Err(BivvyError::RequirementCheckFailed {
            requirement: requirement.to_string(),
            message: format!(
                "Dependency chain exceeds max depth of {}",
                MAX_DEPTH
            ),
        });
    }

    if visited.contains(requirement) {
        return Err(BivvyError::CircularDependency {
            cycle: format!("'{}' appears twice in the chain", requirement),
        });
    }

