    #[test]
    fn multiple_extends_merge_in_order() {
        let server = MockServer::start();

        let first_yaml = r#"
app_name: First
steps:
  step_a:
    command: from-first
  step_shared:
    command: from-first
"#;

        let second_yaml = r#"
app_name: Second
steps:
  step_b:
    command: from-second
  step_shared:
    command: from-second
"#;

        server.mock(|when, then| {
            when.method(GET).path("/first.yml");
            then.status(200).body(first_yaml);
        });

        server.mock(|when, then| {
